const _rumAR: Dict = { "rumor.hakaret.0":"يقولون إنّ %1 أهان %2 على مرأى من الناس.", "rumor.hakaret.1":"أسمعتَ؟ يُروى أنّ %1 سَبَّ %2 بأقذع الكلام.", "rumor.tehdit.0":"يقولون إنّ %1 هدّد %2، وقد طاش عقله كما يُحكى.", "rumor.saldiri.0":"يُروى أنّ %1 اعتدى على %2، حتى سُفك الدم.", "rumor.saldiri.1":"هذا حديث السوق: يقولون إنّ %1 لا يُحاجج إلّا بقبضتيه.", "rumor.kacirma.0":"يقولون إنّ %1 يخطف الناس! وما جرى لـ%2 على كلّ لسان.", "rumor.hirsizlik_tanigi.0":"يُروى أنّ %2 رأى %1 متلبّسًا بالسرقة، ويقولون إنّ يده طويلة.", "rumor.suc_tanigi.0":"يقولون إنّ %2 رأى بأمّ عينه %1 يدبّر أعمالًا مظلمة.", "rumor.dolandiricilik.0":"يقولون إنّ %1 خان الأمانة واحتال على %2.", "rumor.somuru.0":"يُروى أنّ %1 اتّخذ من محنة %2 ورقةً يساوم بها، فما أخبثه من رجل.", "rumor.iftira.0":"يقولون إنّ لسان %1 مسموم، وقد حفر لـ%2 بئرًا من خلفه.", "rumor.alay.0":"يُروى أنّ %1 سخر من %2، ويقولون إنّه يلذّ له إذلال الناس.", "rumor.yakinima_zarar.0":"يقولون إنّ بسبب %1 أُضرمت النار في دار %2.", "rumor.flort_tanigi.0":"يقولون إنّ عين %1 تشرد إلى الغريبات، وقد رآه %2.", "rumor.flort_tanigi.1":"يُروى أنّ %1 خفيفٌ في أمور القلب، هكذا يقولون.", "rumor.reddedilme.0":"يقولون إنّ %1 يستجدي الوصال من باب إلى باب، وقد ردّه %2 خائبًا.", "rumor.comert_hediye.0":"يقولون إنّ %1 رجلٌ سخيّ اليد، وهديّته إلى %2 على كلّ لسان.", "rumor.sadaka.0":"يُروى أنّ %1 يرعى الفقراء والمساكين، وقد نال %2 من خيره.", "rumor.yardim.0":"يقولون إنّ %1 وقف إلى جانب %2 في يوم عسرته، فما أكرمه من رجل.", "rumor.borc_kurtarma.0":"يُروى أنّ %1 انتشل %2 من وحل الديون، ومثله قليلٌ نادر.", "rumor.hayat_kurtarma.0":"يقولون إنّ %1 أنقذ حياة %2! ويدعونه بطلًا.", "rumor.savunma.0":"يُروى أنّ %1 لم يخذل %2، بل وقف دونه وقفة الأبطال.", "rumor.ibadet_tanigi.0":"ثمّة من رأى %1 في صلواته، ويقولون إنّه رجلٌ تقيّ.", "rumor.ihanet.0":"يقولون إنّ %1 رجلٌ لا يُؤتمن، وقد طُعن %2 من خلف ظهره.", "rum.title":"الإشاعات عنك", "rum.none":"ليس ثمّة قولٌ يتناقله الناس عنك الآن.", "rum.bribe":"حاولتَ إسكات الألسنة بالرشوة، لكنّ أحدهم ثرثر، فاستفحل الأمر.", "rum.intensity":"الحِدّة", "rum.confront.win":"اضطُرّ إلى ابتلاع كلامه في وجهك؛ فخمدت الإشاعة.", "rum.confront.lose":"ارتدّت المواجهة عليك؛ فاشتعلت الإشاعة.", "rum.spread.win":"نشرتَ الخبر بنفسك؛ فعلا صيتُك.", "rum.silence.win":"وُزِّعت %1 قطعة نقدية في الأيدي المناسبة؛ فنسيت الألسنة الثرثارة." };
const _rumRU: Dict = { "rumor.hakaret.0":"Говорят, %1 опозорил %2 при всём честном народе.", "rumor.hakaret.1":"Слыхал? %1 наговорил %2 такого, что уши вянут.", "rumor.tehdit.0":"Говорят, %1 пригрозил %2 — совсем, мол, рассудок потерял.", "rumor.saldiri.0":"Говорят, %1 набросился на %2. Кровь пролилась.", "rumor.saldiri.1":"На базаре только и судачат: %1, мол, кулаками разговаривает.", "rumor.kacirma.0":"%1 людей похищает! Что стряслось с %2 — у всех на устах.", "rumor.hirsizlik_tanigi.0":"%2 застал %1 за нечистым делом. На руку нечист, говорят.", "rumor.suc_tanigi.0":"%2 своими глазами видел, как %1 тёмные дела творит.", "rumor.dolandiricilik.0":"%1 доверие обманул; %2, говорят, надул.", "rumor.somuru.0":"Говорят, %1 беду %2 себе в выгоду обратил. Двуличный, мол.", "rumor.iftira.0":"У %1 язык что змеиное жало — за спиной у %2 яму копал.", "rumor.alay.0":"Говорят, %1 насмехался над %2; унижать любит.", "rumor.yakinima_zarar.0":"Из-за %1 в дом %2 беда пришла.", "rumor.flort_tanigi.0":"У %1 глаз на сторону косит; %2 это приметил.", "rumor.flort_tanigi.1":"%1 в сердечных делах больно прыток, так говорят.", "rumor.reddedilme.0":"%1 от двери к двери любви выпрашивает; от %2 от ворот поворот получил.", "rumor.comert_hediye.0":"%1, говорят, рука щедрая; подарок его для %2 у всех на языке.", "rumor.sadaka.0":"%1 о бедных да убогих печётся; и %2 от него не обделён.", "rumor.yardim.0":"Говорят, %1 в чёрный день %2 не покинул. Достойный, мол, человек.", "rumor.borc_kurtarma.0":"Говорят, %1 вытащил %2 из долговой ямы. Такое нечасто сыщешь.", "rumor.hayat_kurtarma.0":"%1 жизнь %2 спас! Героем величают.", "rumor.savunma.0":"%1 не бросил %2 в беде; доблестно встал на защиту.", "rumor.ibadet_tanigi.0":"Видали %1 за молитвой; человек, мол, набожный.", "rumor.ihanet.0":"%1, говорят, человек ненадёжный; %2 в спину предал.", "rum.title":"Слухи о тебе", "rum.none":"Про тебя нынче никаких толков не ходит.", "rum.bribe":"Ты хотел мздой рты позатыкать, да кто-то проболтался: дело только пуще раздулось.", "rum.intensity":"сила", "rum.confront.win":"Ему пришлось проглотить слова тебе в лицо; слух угас.", "rum.confront.lose":"Стычка обернулась против тебя; слух разгорелся.", "rum.spread.win":"Ты сам пустил молву; слава твоя растёт.", "rum.silence.win":"%1 акче ушли в нужные руки; болтливые языки забыли." };
